eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   d1Slides: () => (/* binding */ d1Slides),\n/* harmony export */   d2Slides: () => (/* binding */ d2Slides)\n/* harmony export */ });\nconst d1Slides = [\n    {\n        heading: \"AI & LLM Foundation\",\n        subheading: \"Day 1 — AI IN ACTION\",\n        body: [\n            \"Bạn đang d\\xf9ng AI mỗi ng\\xe0y — nhưng thực sự b\\xean trong n\\xf3 đang l\\xe0m g\\xec?\"\n        ]\n    },\n    {\n        heading: \"Agenda — Day 1\",\n        subheading: \"Từ “nghe AI” đến “gọi AI” trong một ng\\xe0y\",\n        body: [\n            \"Bức tranh AI & c\\xe1c tầng của AI\",\n            \"Lịch sử AI 70 năm\",\n            \"B\\xean trong LLM: cơ chế vận h\\xe0nh\",\n            \"Từ LLM đến AI Agent\",\n            \"Landscape: model h\\xf4m nay & cuộc đua hiện tại\",\n            \"Chọn model & chi ph\\xed token\",\n            \"Gọi API lần đầu\",\n            \"Tổng kết — những \\xfd để mang về\"\n        ]\n    },\n    {\n        heading: \"AI, ML, Deep Learning, GenAI, LLM — nằm ở đ\\xe2u trong c\\xf9ng một hệ?\",\n        body: [\n            \"AI — chiếc \\xf4 lớn nhất: mọi hệ thống c\\xf3 yếu tố “th\\xf4ng minh”.\",\n            \"Machine Learning — học từ dữ liệu thay v\\xec viết luật tay.\",\n            \"Deep Learning — mạng nơ-ron nhiều tầng tự học đặc trưng.\",\n            \"Generative AI — sinh nội dung mới: văn bản, ảnh, code.\",\n            \"LLM — model nền chuy\\xean ng\\xf4n ngữ, tim của l\\xe0n s\\xf3ng hiện nay.\"\n        ],\n        takeaway: \"LLM kh\\xf4ng phải to\\xe0n bộ AI — nhưng n\\xf3 l\\xe0 tầng nền của gần hết trải nghiệm AI bạn d\\xf9ng h\\xf4m nay.\"\n    },\n    {\n        heading: \"Ba nh\\xf3m AI ch\\xednh: ph\\xe2n loại \\xb7 sinh nội dung \\xb7 h\\xe0nh động\",\n        body: [\n            \"Discriminative AI — giỏi ph\\xe2n loại, dự đo\\xe1n: lọc spam, ph\\xe1t hiện gian lận, nhận diện ảnh (Input → một nh\\xe3n, một con số).\",\n            \"Generative AI — sinh ra thứ mới: văn bản, ảnh, code (ChatGPT, Claude, Midjourney — Prompt → nội dung mới).\",\n            \"Agentic AI — nhận mục ti\\xeau rồi tự l\\xe0m nhiều bước: lập kế hoạch, d\\xf9ng c\\xf4ng cụ, h\\xe0nh động (Goal → Plan → Action).\"\n        ],\n        takeaway: \"LLM l\\xe0 engine chung của cả Generative lẫn Agentic. H\\xe0nh tr\\xecnh kh\\xf3a học: LLM Foundation → Agent → Multi-Agent → Deploy → Evaluate.\"\n    },\n    {\n        heading: \"Lịch sử AI 70 năm\",\n        subheading: \"Khai sinh, 2 lần m\\xf9a đ\\xf4ng, c\\xe1ch tiếp cận chạm trần → từ model đơn lẻ sang system c\\xf3 khả năng h\\xe0nh động như agent\",\n        body: []\n    },\n    {\n        heading: \"1980: Hệ chuy\\xean gia (Expert System)\",\n        body: [\n            \"Đặt lại vấn đề: “Nếu AI chỉ giải thật tốt một loại b\\xe0i to\\xe1n chuy\\xean m\\xf4n hẹp th\\xec sao?” → sự ra đời của expert systems.\",\n            \"AI đổi chiến lược: th\\xf4i theo đuổi tr\\xed tuệ tổng qu\\xe1t, tập trung giải thật tốt một miền hẹp bằng c\\xe1ch m\\xe3 h\\xf3a tri thức chuy\\xean gia th\\xe0nh luật.\"\n        ]\n    },\n    {\n        heading: \"2009: Fei-Fei Li v\\xe0 ImageNet — cuộc c\\xe1ch mạng của dữ liệu\",\n        body: [\n            \"Trong khi cả ng\\xe0nh chạy theo thuật to\\xe1n th\\xf4ng minh hơn, Fei-Fei Li chọn con đường kh\\xe1c: x\\xe2y bộ dữ liệu lớn hơn — 14 triệu ảnh g\\xe1n nh\\xe3n tay, hơn 20.000 loại vật.\",\n            \"Ba năm sau, ch\\xednh bộ dữ liệu đ\\xf3 l\\xe0 s\\xe2n khấu cho c\\xfa nổ AlexNet 2012.\"\n        ],\n        takeaway: \"Đ\\xf4i khi dữ liệu tốt hơn đ\\xe1nh bại thuật to\\xe1n kh\\xf4n hơn.\",\n        source: \"Deng, J. et al. 2009, “ImageNet: A Large-Scale Hierarchical Image Database”, CVPR \\xb7 Fei-Fei Li, TED 2015\"\n    },\n    {\n        heading: \"2017: Transformer\",\n        body: [\n            \"Transformer l\\xe0 bước ngoặt v\\xec n\\xf3 cho m\\xf4 h\\xecnh hiểu ng\\xf4n ngữ theo c\\xe1ch linh hoạt hơn: mỗi từ c\\xf3 thể nh\\xecn sang những từ quan trọng kh\\xe1c trong cả c\\xe2u, thay v\\xec chỉ đi tuần tự từng bước.\",\n            \"Trở th\\xe0nh nền m\\xf3ng kỹ thuật cho GPT, BERT v\\xe0 to\\xe0n bộ l\\xe0n s\\xf3ng LLM sau đ\\xf3.\"\n        ]\n    },\n    {\n        heading: \"2022: ChatGPT\",\n        body: [\n            \"ChatGPT xuất hiện như một trải nghiệm đại ch\\xfang.\",\n            \"Lần đầu ti\\xean rất đ\\xf4ng người d\\xf9ng phổ th\\xf4ng c\\xf3 thể trực tiếp chạm v\\xe0o một m\\xf4 h\\xecnh ng\\xf4n ngữ mạnh, qua một giao diện đơn giản đến mức ai cũng hiểu c\\xe1ch d\\xf9ng.\"\n        ]\n    },\n    {\n        heading: \"LLM l\\xe0 g\\xec? — một bộ n\\xe0o nền, kh\\xf4ng phải một chatbot\",\n        body: [\n            \"LLM (Large Language Model) l\\xe0 m\\xf4 h\\xecnh ng\\xf4n ngữ rất lớn, thường dựa tr\\xean kiến tr\\xfac Transformer, được luyện tr\\xean h\\xe0ng ngh\\xecn tỷ mảnh chữ để học c\\xe1ch đo\\xe1n mảnh chữ tiếp theo trong ngữ cảnh.\",\n            \"Nhờ được luyện đủ rộng, n\\xf3 trở th\\xe0nh một nền chung: c\\xf9ng một model l\\xe0m được rất nhiều việc (chatbot, t\\xf3m tắt, viết code, dịch & ph\\xe2n t\\xedch...).\",\n            \"Chatbot chỉ l\\xe0 một dạng sản phẩm đ\\xf3ng g\\xf3i quanh bộ n\\xe3o đ\\xf3 — lớp \\xe1o b\\xean ngo\\xe0i.\"\n        ],\n        takeaway: \"LLM = bộ n\\xe3o ng\\xf4n ngữ d\\xf9ng chung cho mọi việc — sản phẩm bạn thấy chỉ l\\xe0 lớp \\xe1o b\\xean ngo\\xe0i.\"\n    },\n    {\n        heading: \"B\\xean trong Transformer: đầu ra lu\\xf4n l\\xe0 một ph\\xe2n bố x\\xe1c suất\",\n        body: [\n            \"Với mọi ngữ cảnh, model chấm điểm MỌI từ trong từ vựng — “land” 22%, “forest” 9%… — rồi chọn theo x\\xe1c suất đ\\xf3.\"\n        ],\n        source: \"Transformers, the tech behind LLMs — 3Blue1Brown\"\n    },\n    {\n        heading: \"Sinh văn bản = đo\\xe1n → nối v\\xe0o c\\xe2u → đo\\xe1n tiếp\",\n        body: [\n            \"Mỗi token mới được nối v\\xe0o ngữ cảnh, rồi model chạy lại từ đầu — v\\xf2ng lặp predict → append → rerun.\"\n        ],\n        source: \"Transformers, the tech behind LLMs — 3Blue1Brown\"\n    },\n    {\n        heading: \"Token: model kh\\xf4ng đọc “từ”, model đọc mảnh chữ\",\n        body: [\n            \"Model kh\\xf4ng nh\\xecn từ nguy\\xean vẹn. N\\xf3 cắt văn bản th\\xe0nh c\\xe1c mảnh nhỏ gọi l\\xe0 token: c\\xf3 từ l\\xe0 một mảnh, c\\xf3 từ vỡ ba bốn mảnh, cả dấu c\\xe2u v\\xe0 khoảng trắng cũng l\\xe0 mảnh.\",\n            \"V\\xed dụ: “Hello world” ≈ 2 token, nhưng “Xin ch\\xe0o” c\\xf3 thể tới 3–4 token.\",\n            \"Tiếng Việt, code, JSON tốn token hơn tiếng Anh thường.\"\n        ],\n        takeaway: \"Mọi thứ model l\\xe0m đều quy ra token — v\\xe0 mỗi token đều c\\xf3 gi\\xe1.\"\n    },\n    {\n        heading: \"Context: b\\xe0n l\\xe0m việc c\\xf3 hạn của model\",\n        body: [\n            \"Mỗi lần trả lời, model chỉ nh\\xecn được một lượng chữ c\\xf3 hạn — gọi l\\xe0 context. H\\xe3y h\\xecnh dung một b\\xe0n l\\xe0m việc: mọi thứ muốn model “thấy” phải b\\xe0y l\\xean b\\xe0n.\",\n            \"Quy đổi: 128K token ≈ một cuốn s\\xe1ch 300 trang; 1M token ≈ 45 cuốn s\\xe1ch tr\\xean b\\xe0n c\\xf9ng l\\xfac.\",\n            \"B\\xe0n đầy qu\\xe1 th\\xec đồ ở giữa b\\xe0n dễ bị bỏ s\\xf3t — đặt điều quan trọng ở giữa một prompt rất d\\xe0i, model c\\xf3 thể “qu\\xean” mất.\"\n        ],\n        takeaway: \"Context c\\xe0ng d\\xe0i c\\xe0ng tốn tiền v\\xe0 c\\xe0ng chậm — b\\xe0n rộng kh\\xf4ng c\\xf3 nghĩa l\\xe0 d\\xf9ng tốt.\",\n        source: \"Liu et al. 2023, “Lost in the Middle” — arxiv.org/abs/2307.03172\"\n    },\n    {\n        heading: \"Attention: mỗi từ được “nh\\xecn sang” những từ quan trọng kh\\xe1c\",\n        body: [\n            \"Thay v\\xec đọc tuần tự từng chữ, cơ chế attention cho ph\\xe9p mỗi token chủ động “quay đầu” nh\\xecn lại c\\xe1c token trước đ\\xf3 trong c\\xe2u.\",\n            \"Chấm điểm mức độ li\\xean quan của từng token đối với nghĩa của m\\xecnh.\",\n            \"Kh\\xf3a nghĩa theo ngữ cảnh — “n\\xf3” l\\xe0 quyển s\\xe1ch hay c\\xe1i t\\xfai, t\\xf9y theo n\\xf3 ch\\xfa \\xfd v\\xe0o từ n\\xe0o.\"\n        ],\n        takeaway: \"Đ\\xe2y ch\\xednh l\\xe0 chữ T trong GPT — v\\xe0 l\\xe0 l\\xfd do model hiểu ngữ cảnh tốt hơn hẳn c\\xe1c thế hệ trước.\",\n        source: \"Attention in transformers, step-by-step — 3Blue1Brown\"\n    },\n    {\n        heading: \"Hiểu attention để d\\xf9ng AI hiệu quả: quản context = quản sự ch\\xfa \\xfd\",\n        body: [\n            \"Đặt điều quan trọng đầu – cuối: đầu v\\xe0 cuối prompt được ch\\xfa \\xfd nhiều nhất; y\\xeau cầu quan trọng đừng ch\\xf4n giữa.\",\n            \"Giữ b\\xe0n l\\xe0m việc sạch: context r\\xe1c = attention r\\xe1c. Khi chat d\\xe0i, t\\xf3m tắt lại; khi vibe code, đưa đ\\xfang file li\\xean quan.\",\n            \"Cho tra sổ thay v\\xec bắt nhớ: t\\xe0i liệu d\\xe0i, lấy đoạn li\\xean quan nh\\xe9t v\\xe0o context (RAG) thay v\\xec tr\\xf4ng chờ model nhớ hết.\"\n        ],\n        takeaway: \"Agent mạnh kh\\xf4ng phải v\\xec context khổng lồ — m\\xe0 v\\xec n\\xf3 c\\xf3 tools để lấy đ\\xfang thứ v\\xe0o b\\xe0n l\\xe0m việc đ\\xfang l\\xfac.\"\n    },\n    {\n        heading: \"Tham số (parameter): những “khớp nối” model học được\",\n        body: [\n            \"GPT-3 (2020) — 175 tỷ tham số: một “b\\xe1c sĩ đa năng” — mọi token đều đi qua to\\xe0n bộ khớp nối (dense).\",\n            \"Kimi K3 (2026) — 2.800 tỷ tham số: một “bệnh viện đa khoa” — mỗi token chỉ gọi v\\xe0i chuy\\xean gia (MoE).\",\n            \"Luật chơi 2020–2024: cứ th\\xeam compute + dữ liệu l\\xe0 model kh\\xf4n l\\xean một c\\xe1ch dự đo\\xe1n được (scaling law).\"\n        ],\n        takeaway: \"Nhiều tham số ≠ tốn hơn tuyến t\\xednh — nhờ MoE, “bệnh viện” lớn gấp 16 lần m\\xe0 chi ph\\xed mỗi ca kh\\xe1m gần như kh\\xf4ng đổi.\",\n        source: \"MoE — Shazeer et al. 2017 \\xb7 Kimi K3 — k3-kimi.com\"\n    },\n    {\n        heading: \"LLM được tạo ra như thế n\\xe0o? — đọc nhiều, được chỉ, được uốn nắn, luyện đề\",\n        body: [\n            \"① Pre-training — “đọc cả thư viện”: học tiếng n\\xf3i v\\xe0 kiến thức từ h\\xe0ng ngh\\xecn tỷ token.\",\n            \"② SFT — “được chỉ c\\xe1ch trả lời”: học theo v\\xed dụ mẫu để ra d\\xe1ng trợ l\\xfd.\",\n            \"③ RLHF/DPO — “được uốn nắn”: học theo phản hồi con người, an to\\xe0n v\\xe0 dễ chịu hơn.\",\n            \"④ Luyện suy luận — “giải đề tự chấm” (từ 2025): luyện to\\xe1n/code c\\xf3 đ\\xe1p \\xe1n kiểm chứng được.\"\n        ],\n        takeaway: \"Đọc vạn cuốn s\\xe1ch chưa chắc biết trả lời phỏng vấn — đ\\xf3 l\\xe0 l\\xfd do cần bước ②③④.\",\n        source: \"Ouyang et al. 2022, InstructGPT \\xb7 Rafailov et al. 2023, DPO\"\n    },\n    {\n        heading: \"RLHF: ba bước uốn cỗ m\\xe1y đo\\xe1n token th\\xe0nh trợ l\\xfd biết nghe lời\",\n        body: [\n            \"① Model viết nhiều c\\xe2u trả lời cho c\\xf9ng một c\\xe2u hỏi.\",\n            \"② Người chấm xếp hạng c\\xe1c c\\xe2u trả lời → huấn luyện reward model chấm điểm thay người.\",\n            \"③ Huấn luyện theo điểm: c\\xe2u trả lời ghi điểm cao được tăng x\\xe1c suất, lặp lại h\\xe0ng ngh\\xecn lần.\"\n        ],\n        takeaway: \"Cỗ m\\xe1y đo\\xe1n token + điểm xếp hạng của con người → trợ l\\xfd helpful \\xb7 harmless \\xb7 honest.\",\n        source: \"Ouyang et al. 2022, InstructGPT \\xb7 DPO 2023\"\n    },\n    {\n        heading: \"Giới hạn bẩm sinh: học giả trong bong b\\xf3ng\",\n        body: [\n            \"Bong b\\xf3ng thời gian: model bị “đ\\xf3ng băng” tại ng\\xe0y ngừng đọc (knowledge cutoff).\",\n            \"N\\xf3i chắc như đ\\xfang rồi: model tối ưu cho c\\xe2u nghe hợp l\\xfd, kh\\xf4ng phải tra sự thật — n\\xean c\\xf3 thể tự tin m\\xe0 sai (hallucination).\",\n            \"B\\xe0n l\\xe0m việc c\\xf3 hạn: context c\\xf3 trần; qu\\xe1 d\\xe0i vừa tốn tiền vừa dễ bỏ s\\xf3t th\\xf4ng tin ở giữa.\"\n        ],\n        takeaway: \"“Biết nhiều” kh\\xe1c “l\\xe0m được”: dữ liệu mới v\\xe0 h\\xe0nh động thật cần tools/retrieval/workflow.\",\n        source: \"“Why does it work? We don’t know...” — Łukasz Kaiser, đồng t\\xe1c giả Attention Is All You Need\"\n    },\n    {\n        heading: \"V\\xec sao model vẫn sai: n\\xf3 rất giỏi học vẹt đường tắt\",\n        body: [\n            \"Ph\\xe2n loại spam: model thực chất học “đếm số hyperlink trong email” — email sạch nhưng nhiều link vẫn bị g\\xe1n spam.\",\n            \"C\\xe2u chủ quan vs kh\\xe1ch quan: model học “c\\xf3 phải c\\xe2u tr\\xedch từ film review kh\\xf4ng” — ăn gian theo nguồn gốc c\\xe2u, kh\\xf4ng phải nội dung.\",\n            \"Suy luận ng\\xf4n ngữ (MNLI): model học “c\\xe2u c\\xf3 động từ phủ định” — đổi cấu tr\\xfac dữ liệu test l\\xe0 điểm tụt ngay.\"\n        ],\n        takeaway: \"Benchmark cao ≠ model hiểu đ\\xfang thứ bạn tưởng — lu\\xf4n test tr\\xean dữ liệu của ch\\xednh m\\xecnh.\",\n        source: \"Zhong, Snell, Klein & Steinhardt 2022 \\xb7 Zhong et al. 2023, OpenD5\"\n    },\n    {\n        heading: \"Chain-of-Thought: chỉ th\\xeam “giấy nh\\xe1p”, từ sai th\\xe0nh đ\\xfang\",\n        body: [\n            \"B\\xe0i to\\xe1n: “C\\xf3 5 quả b\\xf3ng tennis. Mua th\\xeam 2 hộp, mỗi hộp 3 quả. Hỏi tổng cộng c\\xf3 bao nhi\\xeau quả?”\",\n            \"Kh\\xf4ng c\\xf3 nh\\xe1p — trả lời ngay: “Đ\\xe1p \\xe1n l\\xe0 27 quả.” ✗ SAI\",\n            \"C\\xf3 giấy nh\\xe1p — “h\\xe3y nghĩ từng bước”: “5 quả + (3\\xd72=6 quả) = 11. Đ\\xe1p \\xe1n l\\xe0 11 quả.” ✓ Đ\\xdaNG\"\n        ],\n        takeaway: \"C\\xf9ng một model, c\\xf9ng một c\\xe2u hỏi — cho n\\xf3 viết nh\\xe1p từng bước, bản chất suy luận lộ ra.\",\n        source: \"Wei et al. 2022, Chain-of-Thought Prompting\"\n    },\n    {\n        heading: \"Từ LLM đến agent: bốn mức độ — mỗi bậc th\\xeam một năng lực\",\n        body: [\n            \"Level 0 — Bộ n\\xe3o suy luận: LLM trần, kh\\xf4ng c\\xf4ng cụ, kh\\xf4ng dữ liệu mới.\",\n            \"Level 1 — C\\xf3 kết nối: + tools (search web, đọc database, gọi API) — vượt khỏi bong b\\xf3ng thời gian.\",\n            \"Level 2 — Biết lập kế hoạch: + tự chia mục ti\\xeau th\\xe0nh nhiều bước, d\\xf9ng nhiều tool nối tiếp, tự kiểm tra kết quả.\",\n            \"Level 3 — Đội agent phối hợp: + nhiều agent chuy\\xean biệt chia việc như một đội ngũ (multi-agent).\"\n        ],\n        takeaway: \"Agent kh\\xf4ng phải “một loại model kh\\xe1c” — đ\\xf3 l\\xe0 LLM được đặt v\\xe0o v\\xf2ng l\\xe0m việc c\\xf3 mục ti\\xeau v\\xe0 h\\xe0nh động.\"\n    },\n    {\n        heading: \"Giải phẫu một agent: 5 bộ phận l\\xe0 một v\\xf2ng lặp\",\n        body: [\n            \"① Goal — mục ti\\xeau cần đạt.\",\n            \"② Reasoning — bộ n\\xe3o LLM chia bước.\",\n            \"③ Tools — search \\xb7 API \\xb7 database \\xb7 code.\",\n            \"④ Action — h\\xe0nh động ra đời thật.\",\n            \"Memory — sổ tay ghi nhớ c\\xe1c bước (ghi/đọc, quan s\\xe1t kết quả → lặp lại).\"\n        ],\n        takeaway: \"Agent = Goal + Reasoning + Tools + Memory + Action — chạy th\\xe0nh v\\xf2ng lặp cho tới khi xong việc.\"\n    },\n    {\n        heading: \"C\\xf9ng một mức năng lực, gi\\xe1 rơi khoảng 10 lần mỗi năm\",\n        body: [\n            \"Việc năm ngo\\xe1i phải d\\xf9ng model đắt nhất — năm nay model rẻ đ\\xe3 l\\xe0m được.\"\n        ],\n        source: \"Tổng hợp từ bảng gi\\xe1 c\\xe1c nh\\xe0 cung cấp, 2023–2026\"\n    },\n    {\n        heading: \"Chọn model theo TẦNG, kh\\xf4ng chọn theo t\\xean\",\n        body: [\n            \"Tầng 1 — Frontier đ\\xf3ng (Fable 5, GPT-5.6 Sol, Opus 4.8): đắt nhất — chỉ trả cho việc thật sự kh\\xf3.\",\n            \"Tầng 2 — Rẻ m\\xe0 mạnh (Sonnet 4.6, Terra, Gemini 3.1 Pro, Kimi K3, Haiku, Flash): giải quyết đa số việc hằng ng\\xe0y — ★ mặc định thử tầng n\\xe0y trước.\",\n            \"Tầng 3 — Self-host / si\\xeau rẻ (Kimi K3 open-weight, DeepSeek, Qwen): khi cần kiểm so\\xe1t dữ liệu hoặc chi ph\\xed quy m\\xf4 lớn.\"\n        ],\n        takeaway: \"Hai lỗi đối xứng: việc đơn giản m\\xe0 gọi frontier → ph\\xed tiền; việc kh\\xf3 m\\xe0 cố d\\xf9ng rẻ → kết quả tệ.\"\n    },\n    {\n        heading: \"Token c\\xf3 gi\\xe1: v\\xe9 v\\xe0o rẻ, v\\xe9 ra đắt gấp 3–5 lần\",\n        body: [\n            \"V\\xe9 v\\xe0o — Input: chữ bạn gửi đi (prompt, system instruction, context, lịch sử chat) — rẻ, model chỉ cần đọc.\",\n            \"V\\xe9 ra — Output: chữ model viết ra — model phải tự sinh từng mảnh một, vừa chậm vừa tốn, đắt gấp 3–5 lần.\",\n            \"V\\xed dụ h\\xf3a đơn 1 lần gọi API: input 1.150 tok \\xd7 $3/1M = $0.00345; output 200 tok \\xd7 $15/1M = $0.003; tổng ≈ $0.0065.\"\n        ],\n        takeaway: \"Input tokens + Output tokens = chi ph\\xed mỗi lần gọi — kiểm so\\xe1t output l\\xe0 n\\xfam vặn lớn nhất.\"\n    },\n    {\n        heading: \"Giải phẫu một prompt: bốn lớp xếp chồng\",\n        body: [\n            \"Lớp 1 — System instruction: “lời dặn đầu ca” — model l\\xe0 ai, cư xử thế n\\xe0o, kh\\xf4ng được l\\xe0m g\\xec.\",\n            \"Lớp 2 — User input: c\\xe2u hỏi/y\\xeau cầu của người d\\xf9ng trong lượt n\\xe0y.\",\n            \"Lớp 3 — Context bổ sung: t\\xe0i liệu, lịch sử chat, dữ liệu tra sổ — phần b\\xe0y l\\xean “b\\xe0n l\\xe0m việc”.\",\n            \"Lớp 4 — Output mong muốn: dạng kết quả (gạch đầu d\\xf2ng? bảng? JSON? d\\xe0i bao nhi\\xeau?).\"\n        ],\n        takeaway: \"Viết r\\xf5 cả 4 lớp = đ\\xe3 l\\xe0m tốt một nửa “prompt engineering”.\"\n    },\n    {\n        heading: \"Hai n\\xfam vặn chọn từ: temperature & top_p\",\n        body: [\n            \"temperature — “n\\xfam vặn độ liều”: T=0 lu\\xf4n chọn từ chắc nhất (ổn định, hợp code & ph\\xe2n t\\xedch); T=1 c\\xe2n bằng tự nhi\\xean; T=2 ph\\xe2n bố phẳng ra (đa dạng, dễ lạc đề).\",\n            \"top_p — “chỉ xem top đầu bảng” (VD p=0.9): giữ nh\\xf3m cộng dồn x\\xe1c suất ≥ 90%, loại đu\\xf4i x\\xe1c suất thấp.\",\n            \"Thường chỉ vặn một trong hai. Hai n\\xfam n\\xe0y kh\\xf4ng l\\xe0m model th\\xf4ng minh hơn — chỉ đổi c\\xe1ch chọn từ, kh\\xf4ng th\\xeam tri thức.\"\n        ],\n        takeaway: \"Mặc định an to\\xe0n: temperature = 0 cho việc cần ổn định — chỉ tăng khi thật sự cần đa dạng.\"\n    }\n];\nconst d2Slides = [\n    {\n        heading: \"X\\xe1c định b\\xe0i to\\xe1n cho AI\",\n        subheading: \"Từ y\\xeau cầu mơ hồ đến Problem Statement r\\xf5 r\\xe0ng — Day 02\",\n        body: []\n    },\n    {\n        heading: \"Agenda — Day 02\",\n        body: [\n            \"S\\xc1NG — Khung l\\xfd thuyết (4h): Problem Discovery (Double Diamond, HCD) \\xb7 Problem Statement & định lượng h\\xf3a \\xb7 PAIR ① AI c\\xf3 th\\xeam gi\\xe1 trị? \\xb7 PAIR ② Automate/Augment → Rule/Workflow/Agent \\xb7 PAIR ③ Reward function & success criteria \\xb7 Khi AI sai & UX/HITL \\xb7 PS ho\\xe0n chỉnh → Go/Not Yet/No-Go.\",\n            \"CHIỀU — Thực h\\xe0nh Lab (4h): t\\xecm 5 b\\xe0i to\\xe1n & điền 3 Problem Card \\xb7 phản biện ch\\xe9o, chốt 1 b\\xe0i to\\xe1n \\xb7 x\\xe1c thực dữ liệu & vẽ quy tr\\xecnh \\xb7 x\\xe1c định giải ph\\xe1p & ra quyết định \\xb7 viết Reflection Log.\",\n            \"B\\xe0i nộp cuối buổi: nhật k\\xfd t\\xecm & lọc b\\xe0i to\\xe1n (c\\xe1 nh\\xe2n) \\xb7 Problem Statement ho\\xe0n chỉnh (nh\\xf3m) \\xb7 nhật k\\xfd phản tư (c\\xe1 nh\\xe2n).\"\n        ],\n        takeaway: \"Mục ti\\xeau: biến y\\xeau cầu mơ hồ th\\xe0nh Problem Statement r\\xf5 r\\xe0ng để ra quyết định.\"\n    },\n    {\n        heading: \"Double Diamond: t\\xecm đ\\xfang vấn đề trước khi t\\xecm giải ph\\xe1p\",\n        body: [\n            \"Diamond 1 — T\\xecm đ\\xfang vấn đề: Discover (mở rộng, khảo s\\xe1t vấn đề căn bản) → Define (thu hẹp, x\\xe1c định đ\\xfang b\\xe0i to\\xe1n gốc).\",\n            \"Diamond 2 — T\\xecm đ\\xfang giải ph\\xe1p: Develop (mở rộng, nhiều giải ph\\xe1p tiềm năng) → Deliver (thu hẹp, chọn v\\xe0 triển khai).\"\n        ],\n        takeaway: \"“Kỹ sư v\\xe0 doanh nh\\xe2n được đ\\xe0o tạo để giải vấn đề. Nh\\xe0 thiết kế được đ\\xe0o tạo để kh\\xe1m ph\\xe1 vấn đề thật.” Giải ph\\xe1p xuất sắc cho sai vấn đề c\\xf3 thể c\\xf2n tệ hơn kh\\xf4ng c\\xf3 giải ph\\xe1p.\",\n        source: \"Don Norman / British Design Council 2005\"\n    },\n    {\n        heading: \"Diamond 1 — T\\xecm đ\\xfang vấn đề\",\n        body: [\n            \"Discover \\xb7 Ph\\xe2n kỳ: quan s\\xe1t thực tế, phỏng vấn người d\\xf9ng, khảo s\\xe1t, nhật k\\xfd h\\xe0nh vi, ph\\xe2n t\\xedch dữ liệu/log hệ thống, bản đồ c\\xe1c b\\xean li\\xean quan.\",\n            \"Define \\xb7 Hội tụ: sơ đồ đồng cảm/gom nh\\xf3m (affinity mapping), 5 Whys, ma trận Impact–Effort, dot voting, How Might We, Problem Statement.\"\n        ],\n        takeaway: \"Ph\\xe2n kỳ để thấu hiểu s\\xe2u sắc, hội tụ để lựa chọn ch\\xednh x\\xe1c.\"\n    },\n    {\n        heading: \"Khởi nguồn từ b\\xe0i to\\xe1n, kh\\xf4ng bắt đầu từ AI\",\n        body: [\n            \"Cursor — “Lệch năng lực cốt l\\xf5i”: từ bỏ mảng AI thiết kế cơ kh\\xed (CAD) để tập trung v\\xe0o AI code editor, nơi đội ngũ am hiểu s\\xe2u quy tr\\xecnh nghiệp vụ.\",\n            \"Artifact — “Sản phẩm tốt ≠ Thị trường lớn”: ứng dụng đọc tin t\\xedch hợp AI xuất sắc nhưng thị trường qu\\xe1 hẹp để thương mại h\\xf3a (đ\\xf3ng cửa 1/2024).\",\n            \"NotebookLM — “Định vị đ\\xfang điểm đau”: tập trung giải quyết nhu cầu hỏi đ\\xe1p, t\\xf3m tắt t\\xe0i liệu c\\xe1 nh\\xe2n v\\xe0 đối chiếu nguồn bằng tr\\xedch dẫn.\"\n        ],\n        takeaway: \"Lộ tr\\xecnh: B\\xe0i to\\xe1n → Quy tr\\xecnh vận h\\xe0nh → Chỉ số đo lường → Giải ph\\xe1p AI.\",\n        source: \"Lenny's Podcast \\xb7 The Verge \\xb7 Google Blog\"\n    },\n    {\n        heading: \"T\\xecm b\\xe0i to\\xe1n AI ở đ\\xe2u? — 4 Lenses\",\n        body: [\n            \"Repetitive — t\\xe1c vụ lặp lại: việc diễn ra thường xuy\\xean, c\\xf4ng đoạn n\\xe0o cần chuẩn h\\xf3a để tự động h\\xf3a?\",\n            \"Time-consuming — ti\\xeau tốn thời gian: khối lượng xử l\\xfd lớn, thời gian hao ph\\xed ở đ\\xe2u (t\\xecm kiếm, đọc hiểu, chờ đợi, định dạng)?\",\n            \"AI Advantage — lợi thế của AI: t\\xe1c vụ đ\\xf2i hỏi ph\\xe2n t\\xedch ngữ cảnh, xử l\\xfd ng\\xf4n ngữ tự nhi\\xean, tổng hợp đa nguồn.\",\n            \"User Pain Points — điểm đau người d\\xf9ng: ai đang gặp kh\\xf3 khăn, ph\\xe0n n\\xe0n hoặc bị tắc nghẽn li\\xean tục?\"\n        ],\n        takeaway: \"Tập trung nhận diện vấn đề; chưa vội đề xuất giải ph\\xe1p — s\\xe0ng lọc b\\xe0i to\\xe1n sẽ diễn ra v\\xe0o buổi chiều.\"\n    },\n    {\n        heading: \"Sai lầm thường gặp — Anti-patterns\",\n        body: [\n            \"Ưu ti\\xean giải ph\\xe1p (Solution-first): x\\xe2y chatbot/agent trước khi l\\xe0m r\\xf5 quy tr\\xecnh vận h\\xe0nh v\\xe0 điểm nghẽn thực tế.\",\n            \"Mơ hồ hiện trạng (No baseline): kh\\xf4ng lượng h\\xf3a tổn thất hiện tại, mất căn cứ đ\\xe1nh gi\\xe1 hiệu quả cải tiến.\",\n            \"Bỏ qua đ\\xe1nh gi\\xe1 (No evaluation): kh\\xf4ng thiết lập kịch bản kiểm thử, chỉ số đo lường hoặc phương \\xe1n đối chứng.\",\n            \"Mập mờ ranh giới (No boundary): kh\\xf4ng r\\xf5 phạm vi tự chủ của AI v\\xe0 thời điểm cần con người ph\\xea duyệt (human-in-the-loop).\"\n        ],\n        takeaway: \"Nếu ph\\xe1t hiện mắc c\\xe1c sai lầm tr\\xean, h\\xe3y quay lại l\\xe0m r\\xf5 Problem Statement trước khi chọn c\\xf4ng nghệ.\"\n    },\n    {\n        heading: \"PAIR Chương 1 — Reframe c\\xe2u hỏi\",\n        body: [\n            \"Thay v\\xec hỏi: “Can we use AI to ______?”\",\n            \"H\\xe3y hỏi hai c\\xe2u: “How might we solve ______?” v\\xe0 “Can AI solve this problem in a unique way?”\"\n        ],\n        takeaway: \"Hỏi về b\\xe0i to\\xe1n trước, về AI sau — AI chỉ l\\xe0 một phương \\xe1n trong nhiều phương \\xe1n khả dĩ.\",\n        source: \"Google PAIR — Ch.1 User Needs + Defining Success\"\n    },\n    {\n        heading: \"Quick Problem Card — khung định h\\xecnh b\\xe0i to\\xe1n\",\n        body: [\n            \"B\\xe0i to\\xe1n (1 c\\xe2u): vấn đề cụ thể cần giải quyết, kh\\xf4ng bao gồm giải ph\\xe1p.\",\n            \"Đối tượng ảnh hưởng: c\\xe1 nh\\xe2n/bộ phận chịu t\\xe1c động trực tiếp.\",\n            \"Quy tr\\xecnh hiện tại: c\\xe1c bước vận h\\xe0nh thủ c\\xf4ng hoặc tự động hiện tại.\",\n            \"N\\xfat thắt & t\\xe1c động: kh\\xe2u g\\xe2y chậm trễ/sai s\\xf3t/lặp lại v\\xe0 hệ quả cụ thể.\",\n            \"Chỉ số đo th\\xe0nh c\\xf4ng: chỉ số định lượng chứng minh hiệu quả cải tiến.\",\n            \"Định hướng giải ph\\xe1p: No AI / Rule / Workflow / Agent / chưa x\\xe1c định.\"\n        ]\n    },\n    {\n        heading: \"C\\xe2u hỏi khai th\\xe1c b\\xe0i to\\xe1n\",\n        body: [\n            \"01. Quy tr\\xecnh hiện tại như thế n\\xe0o? (c\\xf4ng cụ, c\\xe1c bước, b\\xe0n giao th\\xf4ng tin)\",\n            \"02. N\\xfat thắt nằm ở đ\\xe2u? (bước n\\xe0o chậm, dễ sai s\\xf3t, lặp lại)\",\n            \"03. Hao ph\\xed hiện tại l\\xe0 bao nhi\\xeau? (thời gian, chi ph\\xed nh\\xe2n sự, SLA, cơ hội bỏ lỡ)\",\n            \"04. Ti\\xeau ch\\xed th\\xe0nh c\\xf4ng đo bằng g\\xec?\",\n            \"05. Hậu quả khi xảy ra sai s\\xf3t? (phạm vi tự quyết của AI, điểm cần con người ph\\xea duyệt)\",\n            \"06. C\\xf3 giải ph\\xe1p phi AI đơn giản hơn? (quy tắc, checklist, quy tr\\xecnh, t\\xe0i liệu hướng dẫn)\"\n        ]\n    },\n    {\n        heading: \"Định lượng h\\xf3a b\\xe0i to\\xe1n\",\n        body: [\n            \"01 \\xb7 Baseline — hiện trạng: mức hao ph\\xed hiện tại l\\xe0 bao nhi\\xeau, bằng con số cụ thể?\",\n            \"02 \\xb7 Target — mục ti\\xeau: kỳ vọng cải thiện ở mức độ n\\xe0o, ngưỡng cụ thể l\\xe0 g\\xec?\",\n            \"03 \\xb7 Measurement — đo lường: chỉ số n\\xe0o chứng minh hiệu quả, c\\xe1ch thu thập?\",\n            \"V\\xed dụ: thời gian ho\\xe0n th\\xe0nh r\\xfat ngắn từ 90 ph\\xfat xuống dưới 30 ph\\xfat \\xb7 tỷ lệ lỗi ph\\xe2n loại giảm từ 20% xuống dưới 5% \\xb7 cắt giảm 40% c\\xe2u hỏi tr\\xf9ng lặp cần TA xử l\\xfd.\"\n        ],\n        takeaway: \"Điểm đau chưa được định lượng th\\xec kh\\xf4ng thể x\\xe1c định gi\\xe1 trị thực tế của AI.\"\n    },\n    {\n        heading: \"Thiết lập chỉ số: Output & Input Metric\",\n        body: [\n            \"Output metric — kết quả cuối c\\xf9ng: thời lượng ho\\xe0n tất quy tr\\xecnh giảm bao nhi\\xeau? tỷ lệ sai s\\xf3t/chất lượng đầu ra thay đổi thế n\\xe0o? gi\\xe1 trị thực tế người d\\xf9ng nhận được r\\xf5 n\\xe9t hơn?\",\n            \"Input metrics — c\\xe1c đ\\xf2n bẩy: tỷ lệ c\\xe2u hỏi được ph\\xe2n loại ch\\xednh x\\xe1c \\xb7 tỷ lệ y\\xeau cầu được chuyển tiếp hỗ trợ kịp thời \\xb7 thời gian TA hiệu chỉnh bản nh\\xe1p phản hồi.\"\n        ],\n        takeaway: \"“N\\xe2ng cao hiệu suất” kh\\xf4ng phải chỉ số — cần gắn với hiện trạng, mục ti\\xeau v\\xe0 phương ph\\xe1p đo.\",\n        source: \"Amplitude — North Star Playbook \\xb7 Lenny Rachitsky\"\n    },\n    {\n        heading: \"Ba bước quyết định AI theo PAIR\",\n        body: [\n            \"Bước ① — Giao điểm nhu cầu \\xd7 thế mạnh AI: b\\xe0i to\\xe1n của bạn c\\xf3 nằm trong nh\\xf3m việc AI l\\xe0m tốt hơn hẳn rule/heuristic kh\\xf4ng?\",\n            \"Bước ② — Automate hay Augment: AI thay thế hay hỗ trợ con người? Mức tự động h\\xf3a tăng dần theo độ tin cậy v\\xe0 rủi ro.\",\n            \"Bước ③ — Reward function & ti\\xeau ch\\xed th\\xe0nh c\\xf4ng: định nghĩa “đ\\xfang/sai” của hệ thống (precision ↔ recall) v\\xe0 ngưỡng th\\xe0nh c\\xf4ng đo được.\"\n        ],\n        takeaway: \"Đi hết 3 bước n\\xe0y, bạn trả lời được cả 4 c\\xe2u hỏi của ng\\xe0y: c\\xf3 cần AI? cấp độ n\\xe0o? đủ r\\xf5 để đo? → Go / Not Yet / No-Go.\",\n        source: \"Google People + AI Guidebook — Ch.1\"\n    },\n    {\n        heading: \"Khi n\\xe0o AI c\\xf3 lợi thế? — 8 trường hợp PAIR (“AI probably better”)\",\n        body: [\n            \"Gợi \\xfd theo từng người (recommendation) \\xb7 Dự đo\\xe1n tương lai (prediction) \\xb7 C\\xe1 nh\\xe2n h\\xf3a (personalization) \\xb7 Hiểu ng\\xf4n ngữ tự nhi\\xean.\",\n            \"Nhận diện cả một lớp thực thể \\xb7 Ph\\xe1t hiện c\\xe1i hiếm & biến đổi (VD gian lận) \\xb7 Agent/bot cho một lĩnh vực cụ thể \\xb7 Nội dung động thay giao diện tĩnh.\"\n        ],\n        takeaway: \"AI chỉ đ\\xe1ng l\\xe0m khi b\\xe0i to\\xe1n nằm trong nh\\xf3m n\\xe0y.\",\n        source: \"PAIR — Ch.1 User Needs + Defining Success\"\n    },\n    {\n        heading: \"Khi n\\xe0o AI KH\\xd4NG tốt hơn? — 6 trường hợp PAIR\",\n        body: [\n            \"Cần duy tr\\xec t\\xednh dự đo\\xe1n được (VD n\\xfat Home/Cancel phải lu\\xf4n ở một chỗ quen thuộc).\",\n            \"Th\\xf4ng tin tĩnh, \\xedt thay đổi — kh\\xf4ng cần AI sinh lại mỗi lần.\",\n            \"Lỗi qu\\xe1 tốn k\\xe9m — chi ph\\xed một lần sai lớn hơn lợi \\xedch nhiều lần đ\\xfang.\",\n            \"Y\\xeau cầu minh bạch tuyệt đối — mọi quyết định phải giải th\\xedch, truy vết được.\",\n            \"Tối ưu tốc độ & chi ph\\xed thấp — AI chỉ th\\xeam độ trễ v\\xe0 chi ph\\xed.\",\n            \"Việc gi\\xe1 trị cao người d\\xf9ng muốn tự l\\xe0m.\"\n        ],\n        takeaway: \"Rule/heuristic dễ build, dễ giải th\\xedch, dễ debug v\\xe0 bảo tr\\xec hơn — nếu n\\xf3 giải quyết được, đ\\xf3 l\\xe0 lựa chọn tối ưu.\",\n        source: \"PAIR — Ch.1 User Needs + Defining Success\"\n    },\n    {\n        heading: \"Hệ thống AI = Model + Context + Planning + Tools\",\n        body: [\n            \"Model — tư duy & s\\xe1ng tạo: đọc hiểu, soạn thảo, tổng hợp, ph\\xe2n loại, gợi \\xfd.\",\n            \"Context — tri thức chuy\\xean biệt: cơ sở dữ liệu, t\\xe0i liệu nghiệp vụ, hồ sơ lịch sử.\",\n            \"Planning — điều phối quy tr\\xecnh: tự động ph\\xe2n r\\xe3 t\\xe1c vụ phức tạp, linh hoạt điều chỉnh.\",\n            \"Tools — li\\xean kết hệ thống: t\\xedch hợp CRM, database, lịch l\\xe0m việc, API b\\xean thứ ba.\"\n        ],\n        takeaway: \"Giải ph\\xe1p AI l\\xe0 một HỆ THỐNG — model chỉ l\\xe0 một th\\xe0nh phần.\",\n        source: \"Anthropic — Building effective agents \\xb7 Chip Huyen — AI Engineering\"\n    },\n    {\n        heading: \"Automation vs Augmentation\",\n        body: [\n            \"Automate — AI l\\xe0m thay: chọn khi việc kh\\xf3/nh\\xe0m ch\\xe1n/nguy hiểm hoặc cần scale; người d\\xf9ng thiếu kiến thức tự l\\xe0m; c\\xf3 “đ\\xe1p \\xe1n đ\\xfang” mọi người đồng thuận. Đo bằng: hiệu quả tăng \\xb7 an to\\xe0n hơn \\xb7 giảm việc tẻ nhạt.\",\n            \"Augment — AI hỗ trợ con người: chọn khi người d\\xf9ng th\\xedch tự l\\xe0m việc đ\\xf3; stakes cao (tiền bạc, ph\\xe1p l\\xfd, sức khỏe); kết quả cần tr\\xe1ch nhiệm c\\xe1 nh\\xe2n; sở th\\xedch kh\\xf3 diễn đạt th\\xe0nh lời. Đo bằng: mức độ th\\xedch th\\xfa \\xb7 cảm gi\\xe1c kiểm so\\xe1t \\xb7 s\\xe1ng tạo tăng.\"\n        ],\n        takeaway: \"Việc đ\\xe3 automate vẫn gần như lu\\xf4n cần human oversight — preview, edit, undo.\",\n        source: \"Google PAIR — Ch.1 User Needs + Defining Success\"\n    },\n    {\n        heading: \"Ba mức giải ph\\xe1p: Rule / Workflow / Agent\",\n        body: [\n            \"Cấp độ 1 — Rule/Script: đầu v\\xe0o ổn định, logic viết được th\\xe0nh if/else, cần đ\\xfang 100%, quy định ph\\xe1p l\\xfd chặt. VD: t\\xednh thuế, chặn spam theo từ kh\\xf3a.\",\n            \"Cấp độ 2 — LLM Feature/Workflow: đầu v\\xe0o đa dạng, đầu ra cần linh hoạt (t\\xf3m tắt, dịch, ph\\xe2n loại), c\\xf3 c\\xe1ch đo chất lượng, người kiểm tra trước khi gửi. VD: t\\xf3m tắt email, chatbot FAQ.\",\n            \"Cấp độ 3 — Agent: nhiều bước, d\\xf9ng nhiều c\\xf4ng cụ, t\\xecnh huống thay đổi li\\xean tục, cần tự ra quyết định, c\\xf3 kiểm so\\xe1t rủi ro r\\xf5 r\\xe0ng. VD: agent nghi\\xean cứu thị trường, coding agent.\"\n        ],\n        takeaway: \"Thứ tự ưu ti\\xean thực dụng: bắt đầu từ b\\xean tr\\xe1i (Rule), chỉ đi sang b\\xean phải khi gi\\xe1 trị tăng hơn độ phức tạp.\"\n    },\n    {\n        heading: \"Một t\\xecnh huống, ba cấp độ giải ph\\xe1p\",\n        body: [\n            \"Cấp độ 1 — Rule: tự động trả lời FAQ, gửi link thời kh\\xf3a biểu, t\\xe0i liệu sửa lỗi c\\xe0i đặt cơ bản, nhắc nhở checklist nộp b\\xe0i.\",\n            \"Cấp độ 2 — Workflow: AI kiểm tra độ đầy đủ của Problem Card, y\\xeau cầu bổ sung nếu thiếu, chuyển cho TA giải quyết.\",\n            \"Cấp độ 3 — Agent: tự động theo d\\xf5i tiến độ nộp b\\xe0i, ph\\xe1t hiện nh\\xf3m học vi\\xean bị kẹt l\\xe2u, chuẩn bị c\\xe2u trả lời v\\xe0 đề xuất TA duyệt.\"\n        ],\n        takeaway: \"Kh\\xf4ng bắt buộc n\\xe2ng cấp tuần tự từ Rule l\\xean Agent — dừng ở cấp tối giản nhất nếu đ\\xe3 đ\\xe1p ứng mục ti\\xeau.\"\n    },\n    {\n        heading: \"Workflow patterns — đủ cho hầu hết b\\xe0i to\\xe1n (Anthropic)\",\n        body: [\n            \"1. Prompt Chaining: chia task th\\xe0nh chuỗi bước tuần tự, c\\xf3 gate kiểm tra giữa c\\xe1c bước (VD viết outline → check → viết b\\xe0i). Đổi độ trễ lấy độ ch\\xednh x\\xe1c.\",\n            \"2. Routing: ph\\xe2n loại input rồi đưa v\\xe0o nh\\xe1nh chuy\\xean biệt (VD CS query → FAQ/refund/kỹ thuật). C\\xe2u dễ đi model rẻ, c\\xe2u kh\\xf3 đi model mạnh.\",\n            \"3. Parallelization: chạy song song rồi tổng hợp, hoặc chạy nhiều lần lấy vote (VD guardrail + response đồng thời). Vote để giảm rủi ro một đầu ra sai.\"\n        ],\n        takeaway: \"Lu\\xf4n ưu ti\\xean giải ph\\xe1p đơn giản nhất; chỉ tăng độ phức tạp khi thực sự cần thiết.\",\n        source: \"Anthropic — Building Effective Agents 2024\"\n    },\n    {\n        heading: \"C\\xe2y quyết định: lựa chọn cấp độ giải ph\\xe1p\",\n        body: [\n            \"Từ b\\xe0i to\\xe1n cốt l\\xf5i đến lựa chọn Rule, Workflow hay Agent.\"\n        ],\n        takeaway: \"Đi từ tr\\xean xuống — mỗi nh\\xe1nh “KH\\xd4NG” l\\xe0 một lần tr\\xe1nh được độ phức tạp kh\\xf4ng cần thiết.\",\n        source: \"Anthropic — Building effective agents \\xb7 Google — Rules of ML\"\n    },\n    {\n        heading: \"Reward function: hệ thống hiểu “đ\\xfang/sai” thế n\\xe0o?\",\n        body: [\n            \"Case: AI gợi \\xfd c\\xe2u trả lời cho c\\xe2u hỏi của 1000 học vi\\xean (K3 & K4).\",\n            \"TP (True Positive): c\\xe2u hỏi nghẽn thật → AI gợi \\xfd đ\\xfang. Học vi\\xean được giải tỏa, TA đỡ tải.\",\n            \"TN (True Negative): c\\xe2u hỏi đ\\xe3 c\\xf3 t\\xe0i liệu sẵn → AI kh\\xf4ng can thiệp. Đ\\xfang — kh\\xf4ng cần gợi \\xfd th\\xeam.\",\n            \"FP (False Positive): AI gợi \\xfd SAI (hallucination), gửi thẳng cho học vi\\xean → học vi\\xean đi sai hướng.\",\n            \"FN (False Negative): học vi\\xean đang kẹt thật nhưng AI bỏ s\\xf3t, kh\\xf4ng gợi \\xfd → học vi\\xean vẫn chờ l\\xe2u.\"\n        ],\n        takeaway: \"Chi ph\\xed của FP v\\xe0 FN KH\\xd4NG đối xứng — b\\xe1o ch\\xe1y giả ≠ bỏ s\\xf3t đ\\xe1m ch\\xe1y. Reward function phải được thiết kế li\\xean chức năng (UX \\xd7 Product \\xd7 Engineering).\",\n        source: \"PAIR — Ch.1 User Needs + Defining Success\"\n    },\n    {\n        heading: \"Precision ↔ Recall: đ\\xe1nh đổi kh\\xf4ng tr\\xe1nh khỏi\",\n        body: [\n            \"Precision cao (TP/(TP+FP)): \\xedt gợi \\xfd nhưng chắc đ\\xfang, người d\\xf9ng tin từng gợi \\xfd — hệ quả: nhiều False Negative, bỏ s\\xf3t học vi\\xean cần gi\\xfap.\",\n            \"Recall cao (TP/(TP+FN)): bao trọn mọi trường hợp cần gi\\xfap — hệ quả: nhiều False Positive, TA phải lọc lại thủ c\\xf4ng.\"\n        ],\n        takeaway: \"Kh\\xf4ng c\\xf3 cấu h\\xecnh đ\\xfang tuyệt đối — phải test điểm c\\xe2n bằng với ch\\xednh người d\\xf9ng.\",\n        source: \"PAIR — Ch.1 User Needs + Defining Success\"\n    },\n    {\n        heading: \"Viết ti\\xeau ch\\xed th\\xe0nh c\\xf4ng m\\xe0 h\\xe0nh động được\",\n        body: [\n            \"Template PAIR: “If {chỉ số cụ thể} for {t\\xednh năng AI} {drops below/goes above} {ngưỡng c\\xf3 nghĩa}, we will {h\\xe0nh động cụ thể}.”\",\n            \"V\\xed dụ (case TA 1000 học vi\\xean): nếu tỷ lệ c\\xe2u trả lời AI gợi \\xfd bị TA sửa > 30% trong 2 tuần, ta sẽ hạ mức tự động về pha 1 (chỉ gợi \\xfd, kh\\xf4ng gửi thẳng cho học vi\\xean).\",\n            \"Checklist trước khi chốt metric: metric c\\xf3 \\xfd nghĩa với mọi người d\\xf9ng? c\\xf3 nh\\xf3m n\\xe0o bị ảnh hưởng ti\\xeau cực? đ\\xe2y l\\xe0 th\\xe0nh c\\xf4ng ng\\xe0y 1 — c\\xf2n ng\\xe0y 1000 th\\xec sao?\"\n        ],\n        takeaway: \"Đừng qu\\xean l\\xean lịch review metric định kỳ — ti\\xeau ch\\xed th\\xe0nh c\\xf4ng cũng cần được bảo tr\\xec theo thời gian.\",\n        source: \"PAIR Worksheet — User Needs\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/slidesData.ts\n");

